import { SandboxError } from '../errors';
import type { TrustedHtmlPolicy } from '../types';

interface TrustedTypesFactory {
  createPolicy(name: string, rules: { createHTML(input: string): unknown }): TrustedHtmlPolicy;
}

let trustedTypesFactory: TrustedTypesFactory | undefined;
let defaultPolicy: TrustedHtmlPolicy | undefined;

/**
 * Assigns `iframe.srcdoc`, going through Trusted Types when the page enforces them.
 * Placing user content is never needed here: the document is generated by this package.
 */
export function assignSrcdoc(
  frame: HTMLIFrameElement,
  html: string,
  policy?: TrustedHtmlPolicy,
): void {
  try {
    frame.srcdoc = html;
    return;
  } catch (error) {
    if (!isTrustedTypesViolation(error)) throw error;
  }

  const resolved = policy ?? getDefaultPolicy();
  try {
    frame.srcdoc = resolved.createHTML(html) as unknown as string;
  } catch (error) {
    throw new SandboxError(
      'trusted-types',
      'The page enforces Trusted Types and blocked the "mica-sandbox" policy. ' +
        'Allow it with `trusted-types mica-sandbox` or pass `trustedTypesPolicy`.',
      { cause: error },
    );
  }
}

function getDefaultPolicy(): { createHTML(input: string): unknown } {
  if (defaultPolicy) return defaultPolicy;

  trustedTypesFactory ??= (globalThis as { trustedTypes?: TrustedTypesFactory }).trustedTypes;
  if (!trustedTypesFactory) {
    throw new SandboxError(
      'trusted-types',
      'The page blocked iframe.srcdoc but Trusted Types is unavailable',
    );
  }

  try {
    defaultPolicy = trustedTypesFactory.createPolicy('mica-sandbox', {
      createHTML: (input: string) => input,
    });
  } catch (error) {
    throw new SandboxError(
      'trusted-types',
      'The page enforces Trusted Types and does not allow the "mica-sandbox" policy. ' +
        'Allow it with `trusted-types mica-sandbox` or pass `trustedTypesPolicy`.',
      { cause: error },
    );
  }

  return defaultPolicy;
}

function isTrustedTypesViolation(error: unknown): boolean {
  return error instanceof TypeError && /TrustedHTML|trusted types/i.test(error.message);
}

/** Reuses a nonce already present on the page so the frame bootstrap satisfies the host CSP. */
export function detectNonce(): string | undefined {
  const script = document.querySelector<HTMLScriptElement>('script[nonce]');
  const nonce = script?.nonce;
  return nonce ? nonce : undefined;
}
